import re, zipfile
def dstyles(path):
    z=zipfile.ZipFile(path)
    out={}
    for i in [1,2,3]:
        s=z.read('xl/worksheets/sheet%d.xml'%i).decode('utf-8')
        styles=[]
        for m in re.finditer(r'<c r="(D[0-9]+)"([^>]*)>', s):
            attr=m.group(2)
            if 'inlineStr' in attr: continue
            sv=re.search(r's="(\d+)"', attr)
            styles.append((m.group(1), sv.group(1) if sv else 'none'))
        out[i]=styles
    return out
inp=dstyles('/tmp/llm_rollout_qnf7pufu/3_99-24_answer_template_7265_input.xlsx')
